import crypto from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import sharp from "sharp";
import yazl from "yazl";
import { COUPLE, COURSE_FIXES, DISH_MATCHES, FOOD_INFO, manifest, MENU_DRAFT, PLACE_RESOLUTIONS, type Entry } from "./manifest";
import { paintCouple, paintFood, paintScene, type Box } from "./paint";

const ROOT = process.cwd();
const OUT = path.join(ROOT, "fixtures", "exports");
const REPLAY = path.join(ROOT, "fixtures", "replay", "claude");

const SYNTHETIC =
  "SYNTHETIC replay for the demo dataset, generated by scripts/seed-demo.ts from scripts/fixtures/manifest.ts on 2026-11-14. No ANTHROPIC_API_KEY was available in the build environment, so these outputs were authored to match the dataset's ground truth instead of recorded from the live API. They exercise the pipeline end to end; they do not measure model accuracy. Re-record with `RECORD=1 DEMO_REPLAY=0 npm run replay:record` and run `npm run test:accuracy` (§13).";

/* -------------------------------- utilities -------------------------------- */

function seedOf(id: string): number {
  return crypto.createHash("sha256").update(id).digest().readUInt32BE(0);
}

/** Converts a local wall time in an IANA zone to a UTC Date (two-pass offset fix). */
export function localToUtc(local: string, tz: string): Date {
  const [d, t] = local.split("T");
  const [y, mo, da] = d!.split("-").map(Number);
  const [h, mi] = t!.split(":").map(Number);
  const guess = Date.UTC(y!, mo! - 1, da!, h!, mi!);
  const offset = (at: number) => {
    const parts = new Intl.DateTimeFormat("en-US", { timeZone: tz, hourCycle: "h23", year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit" }).formatToParts(new Date(at));
    const g = (k: string) => Number(parts.find((p) => p.type === k)!.value);
    return Date.UTC(g("year"), g("month") - 1, g("day"), g("hour"), g("minute")) - at;
  };
  let utc = guess - offset(guess);
  utc = guess - offset(utc);
  return new Date(utc);
}

/** Instagram/Facebook encode UTF-8 bytes as \u00XX escapes (mojibake). */
function mojibakeJson(value: unknown): string {
  const latin = (s: string) => Buffer.from(s, "utf8").toString("latin1");
  const walk = (v: unknown): unknown => (typeof v === "string" ? latin(v) : Array.isArray(v) ? v.map(walk) : v && typeof v === "object" ? Object.fromEntries(Object.entries(v).map(([k, x]) => [k, walk(x)])) : v);
  return JSON.stringify(walk(value), null, 2).replace(/[\u0080-ÿ]/g, (c) => `\\u00${c.charCodeAt(0).toString(16).padStart(2, "0")}`);
}

function zipWrite(file: string, entries: { name: string; data: Buffer; mtime?: Date }[]): Promise<void> {
  return new Promise((resolve, reject) => {
    const z = new yazl.ZipFile();
    for (const e of entries) z.addBuffer(e.data, e.name, { mtime: e.mtime ?? new Date("2026-11-01T00:00:00Z"), compress: !/\.(jpe?g|png|mp4)$/i.test(e.name) });
    z.end();
    fs.mkdirSync(path.dirname(file), { recursive: true });
    z.outputStream.pipe(fs.createWriteStream(file)).on("close", () => resolve()).on("error", reject);
  });
}

const sceneFor: Record<string, string> = { landscape: "outdoor", lake: "outdoor", city: "outdoor", snow: "outdoor", people: "outdoor", object: "home", advert: "outdoor", screen: "home", menu_board: "restaurant" };

type Rendered = { entry: Entry; jpeg: Buffer; faces: Box[]; food: Box[] };

async function render(e: Entry): Promise<Rendered> {
  const seed = seedOf(e.id);
  let svg: string;
  let faces: Box[] = [];
  let food: Box[] = [];
  if (e.food) {
    const p = paintFood(e.food.kind, seed, { faceCorner: e.food.faceCorner });
    svg = p.svg;
    faces = p.faces;
    food = p.food;
  } else if (e.couple) {
    const p = paintCouple(seed);
    svg = p.svg;
    faces = p.faces;
  } else {
    const p = paintScene(e.scene!.kind, seed, { people: e.scene!.people });
    svg = p.svg;
    faces = p.faces;
  }
  const jpeg = await sharp(Buffer.from(svg)).jpeg({ quality: 80 }).toBuffer();
  return { entry: e, jpeg, faces, food };
}

function detectionOracle(r: Rendered) {
  const e = r.entry;
  const round = (b: Box) => b.map((v) => Math.round(v * 1000) / 1000) as Box;
  if (e.food) {
    const info = FOOD_INFO[e.food.kind];
    return {
      has_food_or_drink: true,
      items: info.items.map((it, i) => ({
        dish_name: it.dish_name,
        dish_generic: it.dish_generic,
        category: it.category,
        cuisine: it.cuisine,
        is_homemade_guess: it.homemade,
        confidence: it.confidence,
        bbox: round(r.food[i] ?? r.food[0]!),
      })),
      scene: info.scene,
      people_visible: r.faces.length > 0,
      face_boxes: r.faces.map(round),
      setting_flags: info.setting ?? [],
    };
  }
  return {
    has_food_or_drink: false,
    items: [],
    scene: e.couple ? "outdoor" : (sceneFor[e.scene!.kind] ?? "other"),
    people_visible: r.faces.length > 0,
    face_boxes: r.faces.map(round),
    setting_flags: [],
  };
}

/* ------------------------------- export zips ------------------------------- */

async function buildInstagram(rendered: Rendered[]) {
  const entries: { name: string; data: Buffer }[] = [];
  const posts: unknown[] = [];
  const groups = new Map<string, Rendered[]>();
  for (const r of rendered) {
    const key = r.entry.post ?? r.entry.id;
    groups.set(key, [...(groups.get(key) ?? []), r]);
  }
  for (const group of groups.values()) {
    const first = group[0]!.entry;
    const ts = Math.floor(localToUtc(first.local, first.tz).getTime() / 1000);
    const media = group.map((r) => {
      const t = Math.floor(localToUtc(r.entry.local, r.entry.tz).getTime() / 1000);
      const d = localToUtc(r.entry.local, r.entry.tz);
      const uri = `media/posts/${d.getUTCFullYear()}${String(d.getUTCMonth() + 1).padStart(2, "0")}/${r.entry.id}.jpg`;
      entries.push({ name: uri, data: r.jpeg });
      return {
        uri,
        creation_timestamp: t,
        media_metadata: r.entry.lat !== undefined ? { photo_metadata: { exif_data: [{ latitude: r.entry.lat, longitude: r.entry.lng, device_id: "android-0f3c" }] } } : undefined,
        title: group.length === 1 ? (first.caption ?? "") : "",
        cross_post_source: { source_app: "FB" },
      };
    });
    posts.push(group.length === 1 ? { media, creation_timestamp: ts } : { media, title: first.caption ?? "", creation_timestamp: ts });
  }
  // Two video posts: skipped and counted.
  for (const [i, v] of ["202307", "202405"].entries()) {
    const uri = `media/posts/${v}/reel_${i + 1}.mp4`;
    entries.push({ name: uri, data: Buffer.from("synthetic placeholder video") });
    posts.push({ media: [{ uri, creation_timestamp: 1690000000 + i * 1e7, title: "Summer reel" }] });
  }
  entries.push({ name: "your_instagram_activity/content/posts_1.json", data: Buffer.from(mojibakeJson(posts)) });
  entries.push({ name: "personal_information/personal_information/personal_information.json", data: Buffer.from(mojibakeJson({ profile_user: [{ string_map_data: { Name: { value: COUPLE.partnerA.name } } }] })) });
  entries.push({ name: "start_here.html", data: Buffer.from("<html><body>Your information</body></html>") });
  await zipWrite(path.join(OUT, "aino_instagram.zip"), entries);
}

async function buildTakeout(rendered: Rendered[]) {
  const entries: { name: string; data: Buffer }[] = [];
  let i = 0;
  for (const r of rendered) {
    const e = r.entry;
    const album = e.album ?? `Photos from ${e.local.slice(0, 4)}`;
    const img = `Takeout/Google Photos/${album}/${e.id}.jpg`;
    const ts = Math.floor(localToUtc(e.local, e.tz).getTime() / 1000);
    const formatted = new Date(ts * 1000).toUTCString();
    const geo = e.lat !== undefined ? { latitude: e.lat, longitude: e.lng, altitude: 12.0, latitudeSpan: 0, longitudeSpan: 0 } : { latitude: 0, longitude: 0, altitude: 0, latitudeSpan: 0, longitudeSpan: 0 };
    const sidecar = {
      title: `${e.id}.jpg`,
      description: e.caption ?? "",
      imageViews: "3",
      creationTime: { timestamp: String(ts + 120), formatted },
      photoTakenTime: { timestamp: String(ts), formatted },
      geoData: geo,
      geoDataExif: geo,
      url: "https://photos.google.com/photo/synthetic",
      googlePhotosOrigin: { mobileUpload: { deviceType: "ANDROID_PHONE" } },
    };
    // Mix the two sidecar namings Takeout has used (§7.1 VERIFY).
    const sidecarName = i++ % 3 === 0 ? `${img}.json` : `${img}.supplemental-metadata.json`;
    entries.push({ name: img, data: r.jpeg }, { name: sidecarName, data: Buffer.from(JSON.stringify(sidecar, null, 2)) });
    // Takeout duplicates photos that are also in an album: same file in "Photos from YYYY".
    if (e.album === "Naples 2023" && e.food) {
      const dup = `Takeout/Google Photos/Photos from 2023/${e.id}.jpg`;
      entries.push({ name: dup, data: r.jpeg }, { name: `${dup}.supplemental-metadata.json`, data: Buffer.from(JSON.stringify(sidecar, null, 2)) });
    }
  }
  // Skipped items: a video, a HEIC, a thumbnail under 200×200 px.
  entries.push({ name: "Takeout/Google Photos/Photos from 2024/VID_20240505_191010.mp4", data: Buffer.from("synthetic placeholder video") });
  entries.push({ name: "Takeout/Google Photos/Photos from 2024/VID_20240505_191010.mp4.supplemental-metadata.json", data: Buffer.from(JSON.stringify({ title: "VID_20240505_191010.mp4", photoTakenTime: { timestamp: "1714925410" } })) });
  entries.push({ name: "Takeout/Google Photos/Photos from 2022/IMG_20220601_101010.HEIC", data: Buffer.from("synthetic heic") });
  const tiny = await sharp({ create: { width: 150, height: 150, channels: 3, background: "#cccccc" } }).jpeg().toBuffer();
  entries.push({ name: "Takeout/Google Photos/Photos from 2022/IMG_20220602_090000.jpg", data: tiny });
  entries.push({ name: "Takeout/Google Photos/Photos from 2022/IMG_20220602_090000.jpg.supplemental-metadata.json", data: Buffer.from(JSON.stringify({ title: "IMG_20220602_090000.jpg", photoTakenTime: { timestamp: "1654149600" }, geoData: { latitude: 0, longitude: 0 } })) });
  entries.push({ name: "Takeout/Google Photos/Naples 2023/metadata.json", data: Buffer.from(JSON.stringify({ title: "Naples 2023", description: "", access: "protected", date: { timestamp: "1683849600" } })) });
  entries.push({ name: "Takeout/archive_browser.html", data: Buffer.from("<html><body>Takeout</body></html>") });
  await zipWrite(path.join(OUT, "sam_google_takeout.zip"), entries);
}

/** Small variant exports for the parser tests (§13: every supported variant has a fixture). */
async function buildVariants() {
  const img = await sharp(Buffer.from(paintFood("salmon_soup", 7).svg)).jpeg({ quality: 70 }).toBuffer();
  const ts = Math.floor(localToUtc("2021-09-03T19:30", "Europe/Helsinki").getTime() / 1000);

  // Facebook: a check-in with a place name (export_place path), a photo post, a text post, a friend's comment.
  const fbPosts = [
    {
      timestamp: ts,
      data: [{ post: "First date at Löyly 🧖 the salmon soup!!" }],
      attachments: [
        { data: [{ media: { uri: "your_facebook_activity/posts/media/FirstDate_1/10159.jpg", creation_timestamp: ts, title: "Mobile uploads", description: "First date at Löyly 🧖 the salmon soup!!" } }] },
        { data: [{ place: { name: "Löyly", coordinate: { latitude: 60.15238, longitude: 24.93731 }, address: "Hernesaarenranta 4, Helsinki", url: "https://www.facebook.com/loylyhelsinki" } }] },
      ],
      comments: [{ timestamp: ts + 600, comment: "That soup looks amazing, so happy for you two", author: "A. Friend" }],
      title: "Sam Carter was at Löyly.",
    },
    { timestamp: ts + 86400 * 30, data: [{ post: "Sunday walk, no food today" }], title: "Sam Carter updated his status." },
    { timestamp: ts + 86400 * 60, attachments: [{ data: [{ place: { name: "Café Regatta", coordinate: { latitude: 60.1786, longitude: 24.9095 }, address: "Merikannontie 8, Helsinki" } }] }], data: [{ post: "Korvapuusti time" }], title: "Sam Carter checked in at Café Regatta." },
    { timestamp: ts + 86400 * 90, attachments: [{ data: [{ media: { uri: "your_facebook_activity/posts/media/Reels_1/clip.mp4", creation_timestamp: ts } }] }], title: "Sam Carter posted a video." },
  ];
  await zipWrite(path.join(OUT, "facebook_variant.zip"), [
    { name: "your_facebook_activity/posts/your_posts__check_ins__photos_and_videos_1.json", data: Buffer.from(mojibakeJson(fbPosts)) },
    { name: "your_facebook_activity/posts/media/FirstDate_1/10159.jpg", data: img },
    { name: "your_facebook_activity/posts/media/Reels_1/clip.mp4", data: Buffer.from("video") },
    { name: "start_here.html", data: Buffer.from("<html></html>") },
  ]);

  // Instagram legacy layout: content/posts_1.json at the zip root.
  const igLegacy = [
    { media: [{ uri: "media/posts/202109/legacy_1.jpg", creation_timestamp: ts, title: "Kahvi ja pulla ☕ café crème" }] },
    { media: [{ uri: "media/posts/202109/legacy_2.jpg", creation_timestamp: ts + 3600 }, { uri: "media/posts/202109/legacy_3.jpg", creation_timestamp: ts + 3600 }], title: "Two-photo carousel – Jäätelö!", creation_timestamp: ts + 3600 },
  ];
  await zipWrite(path.join(OUT, "instagram_legacy.zip"), [
    { name: "content/posts_1.json", data: Buffer.from(mojibakeJson(igLegacy)) },
    { name: "media/posts/202109/legacy_1.jpg", data: img },
    { name: "media/posts/202109/legacy_2.jpg", data: img },
    { name: "media/posts/202109/legacy_3.jpg", data: img },
  ]);

  // Something that is not an export at all (US-2 AC5).
  await zipWrite(path.join(OUT, "not_an_export.zip"), [
    { name: "holiday/notes.txt", data: Buffer.from("packing list") },
    { name: "holiday/IMG_0001.jpg", data: img },
  ]);
}

/* -------------------------------- replays -------------------------------- */

function writeReplay(name: string, entries: Record<string, unknown>, provenance = SYNTHETIC) {
  fs.mkdirSync(REPLAY, { recursive: true });
  fs.writeFileSync(path.join(REPLAY, `${name}.json`), JSON.stringify({ _provenance: provenance, entries }, null, 2) + "\n");
}

const sha = (s: string) => crypto.createHash("sha256").update(s.normalize("NFC")).digest("hex");
const coordKey = (lat: number, lng: number) => `${lat.toFixed(3)},${lng.toFixed(3)}`;

function buildReplays(rendered: Rendered[]) {
  const food: Record<string, unknown> = {};
  const text: Record<string, unknown> = {};
  const places: Record<string, unknown> = {};
  for (const r of rendered) {
    const e = r.entry;
    food[`${e.id}.jpg`] = { stop_reason: "end_turn", synthetic: true, output: { image_id: `${e.id}.jpg`, ...detectionOracle(r) } };
    if (e.caption) {
      text[sha(e.caption)] = {
        stop_reason: "end_turn",
        synthetic: true,
        output: {
          text_id: e.id,
          food_mentions: e.text?.food ?? [],
          event_cues: e.text?.cues ?? [],
          sentiment: e.text?.sentiment ?? 0.5,
          mentions_other_people: e.text?.others ?? false,
          sensitive_cues: e.text?.sensitive ?? [],
        },
      };
    }
    if (e.food && e.lat !== undefined && FOOD_INFO[e.food.kind].scene !== "home") {
      const resolved = PLACE_RESOLUTIONS[e.id] ?? { venue_name: null, address: null, city: null, website_url: null, confidence: 0.3, evidence: "No single food venue can be identified with confidence at these coordinates (synthetic dataset)." };
      places[coordKey(e.lat, e.lng!)] = { stop_reason: "end_turn", synthetic: true, output: resolved };
    }
  }
  writeReplay("food_detect", food);
  writeReplay("text_extract", text);
  writeReplay("place_resolve", places);
  writeReplay("dish_match", Object.fromEntries(Object.entries(DISH_MATCHES).map(([k, v]) => [k, { stop_reason: "end_turn", synthetic: true, output: v }])));
  writeReplay("menu_generate", { default: { stop_reason: "end_turn", synthetic: true, output: MENU_DRAFT } });
  writeReplay("menu_course", Object.fromEntries(Object.entries(COURSE_FIXES).map(([k, v]) => [k, { stop_reason: "end_turn", synthetic: true, output: v }])));
}

/* ---------------------------------- main ---------------------------------- */

export async function buildFixtures(): Promise<{ images: number; food: number }> {
  const all = manifest();
  // Make ids unique (random non-food ids can collide).
  const seen = new Map<string, number>();
  for (const e of all) {
    const n = seen.get(e.id) ?? 0;
    seen.set(e.id, n + 1);
    if (n) e.id = `${e.id}_${n}`;
  }
  const rendered: Rendered[] = [];
  const batch = 8;
  for (let i = 0; i < all.length; i += batch) rendered.push(...(await Promise.all(all.slice(i, i + batch).map(render))));

  await buildInstagram(rendered.filter((r) => r.entry.owner === "aino"));
  await buildTakeout(rendered.filter((r) => r.entry.owner === "sam"));
  await buildVariants();
  buildReplays(rendered);

  const oracle = rendered.map((r) => ({ id: r.entry.id, owner: r.entry.owner, file: `${r.entry.id}.jpg`, is_food: !!r.entry.food, dish: r.entry.food ? FOOD_INFO[r.entry.food.kind].items[0]!.dish_name : null, beat: r.entry.beat ?? null }));
  fs.writeFileSync(path.join(ROOT, "fixtures", "manifest.json"), JSON.stringify({ generated: "scripts/seed-demo.ts", couple: COUPLE.name, images: oracle }, null, 2) + "\n");
  return { images: rendered.length, food: rendered.filter((r) => r.entry.food).length };
}
